import React, { useState } from "react";
import { useParams, useNavigate, Link } from "react-router-dom";
import { motion } from "framer-motion";
import {
  FiAlertTriangle,
  FiCalendar,
  FiEdit,
  FiArrowLeft,
  FiTag,
  FiFileText,
  FiAlertCircle,
  FiTrash2,
  FiCheckCircle,
  FiInfo,
  FiTool,
  FiUser,
} from "react-icons/fi";
import { useIncidents } from "../../hooks/Incident/useIncidents";
import { useSorties } from "../../hooks/Sortie/useSorties";
import LoadingSpinner from "../Common/LoadingSpinner";
import { formatDateTime } from "../../utils/helpers";

const fadeInUp = {
  initial: { opacity: 0, y: 20 },
  animate: { opacity: 1, y: 0 },
  transition: { duration: 0.4, ease: "easeOut" },
};

const IncidentDetails = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { useGetById, useRemove, useCloturer } = useIncidents();
  const { useGetById: useGetSortie } = useSorties();
  const { data, isLoading } = useGetById(id);
  const remove = useRemove();
  const cloturer = useCloturer();
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [mesuresCloture, setMesuresCloture] = useState("");
  const [showClotureForm, setShowClotureForm] = useState(false);

  const incident = data?.data;
  const { data: sortieData } = useGetSortie(incident?.id_sortie);
  const sortie = sortieData?.data;

  const handleDelete = async () => {
    try {
      await remove.mutateAsync(id);
      navigate("/incidents");
    } catch (error) {
      // toast déjà géré par le hook useRemove
    }
  };

  const handleCloturer = async () => {
    try {
      await cloturer.mutateAsync({
        id,
        data: mesuresCloture ? { mesures_prises: mesuresCloture } : {},
      });
      setShowClotureForm(false);
    } catch (error) {
      // toast déjà géré par le hook useCloturer
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <LoadingSpinner />
      </div>
    );
  }

  if (!incident) {
    return (
      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        className="text-center py-16"
      >
        <div className="inline-flex items-center justify-center w-20 h-20 rounded-full bg-gray-100 dark:bg-gray-800/50 mb-6">
          <FiInfo className="w-10 h-10 text-gray-400" />
        </div>
        <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-2">
          Incident non trouvé
        </h3>
        <p className="text-gray-500 dark:text-gray-400">
          L'incident que vous recherchez n'existe pas ou a été supprimé.
        </p>
        <button
          onClick={() => navigate("/incidents")}
          className="mt-6 inline-flex items-center gap-2 px-6 py-2.5 text-sm font-medium text-white bg-gradient-to-r from-cyan-600 via-blue-600 to-indigo-600 hover:from-cyan-700 hover:via-blue-700 hover:to-indigo-700 rounded-xl transition-all duration-300 shadow-lg shadow-blue-500/25 hover:shadow-xl hover:shadow-blue-500/35"
        >
          <FiArrowLeft className="w-4 h-4" />
          Retour à la liste
        </button>
      </motion.div>
    );
  }

  const InfoItem = ({ icon: Icon, label, value, highlight = false, children }) => (
    <motion.div
      variants={fadeInUp}
      className={`flex items-start gap-4 p-4 rounded-xl transition-all duration-300 ${
        highlight
          ? "bg-gradient-to-r from-blue-50 to-blue-100/50 dark:from-blue-900/20 dark:to-blue-800/10 border-l-4 border-blue-500"
          : "hover:bg-gray-50 dark:hover:bg-gray-800/30"
      }`}
    >
      <div
        className={`mt-0.5 p-2 rounded-lg ${
          highlight
            ? "bg-blue-100 dark:bg-blue-900/40 text-blue-600 dark:text-blue-400"
            : "bg-gray-100 dark:bg-gray-800 text-gray-500 dark:text-gray-400"
        }`}
      >
        <Icon className="w-5 h-5" />
      </div>
      <div className="flex-1 min-w-0">
        <p className="text-xs font-medium uppercase tracking-wider text-gray-400 dark:text-gray-500">
          {label}
        </p>
        {children || (
          <p className="font-semibold text-gray-900 dark:text-white mt-0.5">
            {value || "Non défini"}
          </p>
        )}
      </div>
    </motion.div>
  );

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      className="space-y-6 max-w-4xl mx-auto px-4"
    >
      <motion.div
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4"
      >
        <div className="flex items-center gap-4">
          <div>
            <div className="flex items-center gap-3">
              <span className="p-2.5 rounded-xl bg-gradient-to-br from-red-500/10 to-orange-500/10">
                <FiAlertTriangle className="w-6 h-6 text-red-600 dark:text-red-400" />
              </span>
              <div>
                <h1 className="text-2xl md:text-3xl font-bold text-gray-900 dark:text-white">
                  Incident{" "}
                  <span className="text-red-600 dark:text-red-400">
                    {incident.type}
                  </span>
                </h1>
                <p className="text-gray-500 dark:text-gray-400 mt-1 flex items-center gap-2 flex-wrap">
                  <span className="flex items-center gap-1 text-sm">
                    <FiFileText className="w-3.5 h-3.5" />
                    N°{incident.id_incident}
                  </span>
                  {sortie && (
                    <>
                      <span className="text-gray-300 dark:text-gray-600">•</span>
                      <span className="flex items-center gap-1 text-sm">
                        {sortie.type} - {sortie.lieu}
                      </span>
                    </>
                  )}
                </p>
              </div>
            </div>
          </div>
        </div>
        <div className="flex gap-2">
          <Link
            to={`/incidents/edit/${incident.id_incident}`}
            className="inline-flex items-center gap-2 px-5 py-2.5 text-sm font-semibold text-white bg-gradient-to-r from-cyan-600 via-blue-600 to-indigo-600 hover:from-cyan-700 hover:via-blue-700 hover:to-indigo-700 rounded-xl transition-all duration-300 shadow-lg shadow-blue-500/25 hover:shadow-xl hover:shadow-blue-500/35 hover:-translate-y-0.5"
          >
            <FiEdit className="w-4 h-4" />
            Modifier
          </Link>
          <button
            onClick={() => setShowDeleteModal(true)}
            className="inline-flex items-center gap-2 px-5 py-2.5 text-sm font-semibold text-white bg-gradient-to-r from-red-600 to-rose-600 hover:from-red-700 hover:to-rose-700 rounded-xl transition-all duration-300 shadow-lg shadow-red-500/25 hover:shadow-xl hover:shadow-red-500/35 hover:-translate-y-0.5"
          >
            <FiTrash2 className="w-4 h-4" />
            Supprimer
          </button>
        </div>
      </motion.div>

      {/* Carte de statut */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className={`rounded-2xl shadow-xl p-6 md:p-8 text-white ${
          incident.cloture
            ? "bg-gradient-to-r from-emerald-500 to-green-600"
            : "bg-gradient-to-r from-red-500 to-rose-600"
        }`}
      >
        <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-6">
          <div className="flex items-center gap-4">
            <div className="p-3 rounded-full bg-white/20">
              {incident.cloture ? (
                <FiCheckCircle className="w-7 h-7" />
              ) : (
                <FiAlertTriangle className="w-7 h-7" />
              )}
            </div>
            <div>
              <p className="text-2xl font-bold">
                {incident.cloture ? "Clôturé" : "Non clôturé"}
              </p>
              <p className="text-sm text-white/80">
                {incident.cloture
                  ? `Clôturé le ${formatDateTime(incident.date_cloture)}`
                  : "Cet incident nécessite un suivi"}
              </p>
            </div>
          </div>
          {!incident.cloture && (
            <button
              onClick={() => setShowClotureForm(true)}
              className="inline-flex items-center gap-2 px-5 py-2.5 text-sm font-semibold text-red-700 bg-white hover:bg-gray-100 rounded-xl transition-all duration-300 shadow-lg"
            >
              <FiCheckCircle className="w-4 h-4" />
              Clôturer l'incident
            </button>
          )}
        </div>
      </motion.div>

      {showClotureForm && (
        <motion.div
          initial={{ opacity: 0, height: 0 }}
          animate={{ opacity: 1, height: "auto" }}
          className="bg-white dark:bg-gray-900 rounded-2xl shadow-xl border border-gray-100/80 dark:border-gray-800/80 p-6"
        >
          <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-3">
            Clôturer l'incident
          </h3>
          <textarea
            value={mesuresCloture}
            onChange={(e) => setMesuresCloture(e.target.value)}
            rows={3}
            placeholder="Mesures prises pour clôturer (optionnel)..."
            className="w-full px-4 py-2.5 text-sm border rounded-lg focus:outline-none border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
          />
          <div className="flex justify-end gap-3 mt-4">
            <button
              onClick={() => setShowClotureForm(false)}
              className="px-5 py-2.5 text-sm font-medium text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-xl transition-colors"
            >
              Annuler
            </button>
            <button
              onClick={handleCloturer}
              disabled={cloturer.isPending}
              className="px-5 py-2.5 text-sm font-semibold text-white bg-green-600 hover:bg-green-700 rounded-xl transition-colors disabled:opacity-60"
            >
              Confirmer la clôture
            </button>
          </div>
        </motion.div>
      )}

      {/* Informations */}
      <motion.div
        initial="initial"
        animate="animate"
        className="bg-white dark:bg-gray-900 rounded-2xl shadow-xl border border-gray-100/80 dark:border-gray-800/80 p-6"
      >
        <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-5 flex items-center gap-3">
          <span className="p-2 rounded-xl bg-gradient-to-br from-blue-500/10 to-cyan-500/10 text-blue-600 dark:text-blue-400">
            <FiInfo className="w-5 h-5" />
          </span>
          Détails de l'incident
        </h3>
        <div className="space-y-2">
          <InfoItem icon={FiTag} label="Type" value={incident.type} highlight />
          <InfoItem
            icon={FiCalendar}
            label="Date et heure"
            value={formatDateTime(incident.date_heure)}
          />
          {sortie && (
            <InfoItem
              icon={FiFileText}
              label="Sortie concernée"
              value={`${sortie.type} - ${sortie.lieu}`}
            />
          )}
          {incident.declared_by && (
            <InfoItem
              icon={FiUser}
              label="Déclaré par"
              value={incident.declared_by}
            />
          )}
          <InfoItem icon={FiFileText} label="Description">
            <p className="text-gray-700 dark:text-gray-300 mt-1 whitespace-pre-line">
              {incident.description}
            </p>
          </InfoItem>
          {incident.mesures_prises && (
            <InfoItem icon={FiTool} label="Mesures prises">
              <p className="text-gray-700 dark:text-gray-300 mt-1 whitespace-pre-line">
                {incident.mesures_prises}
              </p>
            </InfoItem>
          )}
        </div>
      </motion.div>

      {showDeleteModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ type: "spring", damping: 25 }}
            className="bg-white dark:bg-gray-900 rounded-2xl p-6 max-w-md w-full shadow-2xl border border-gray-100 dark:border-gray-800"
          >
            <div className="flex items-center gap-3 text-red-600 dark:text-red-400 mb-4">
              <div className="p-2 rounded-xl bg-red-100 dark:bg-red-900/30">
                <FiAlertCircle className="w-6 h-6" />
              </div>
              <h3 className="text-lg font-bold">Confirmer la suppression</h3>
            </div>
            <p className="text-gray-600 dark:text-gray-400 mb-6 leading-relaxed">
              Êtes-vous sûr de vouloir supprimer cet incident ?
              <br />
              <span className="text-sm text-red-500 font-medium">
                Cette action est irréversible.
              </span>
            </p>
            <div className="flex justify-end gap-3">
              <button
                onClick={() => setShowDeleteModal(false)}
                className="px-5 py-2.5 text-sm font-medium text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-xl transition-colors"
              >
                Annuler
              </button>
              <button
                onClick={handleDelete}
                className="px-5 py-2.5 text-sm font-semibold text-white bg-gradient-to-r from-red-600 to-rose-600 hover:from-red-700 hover:to-rose-700 rounded-xl transition-all duration-300 shadow-lg shadow-red-500/25 hover:shadow-xl hover:shadow-red-500/35"
              >
                <FiTrash2 className="w-4 h-4 inline mr-2" />
                Confirmer la suppression
              </button>
            </div>
          </motion.div>
        </div>
      )}
    </motion.div>
  );
};

export default IncidentDetails;
