import React, { useState } from "react";
import { useParams, useNavigate, Link } from "react-router-dom";
import { motion } from "framer-motion";
import {
  FiTool,
  FiCalendar,
  FiEdit,
  FiArrowLeft,
  FiAlertCircle,
  FiTrash2,
  FiCheckCircle,
  FiClock,
  FiInfo,
  FiDollarSign,
  FiUser,
  FiFileText,
} from "react-icons/fi";
import { useReparations } from "../../hooks/Reparation/useReparations";
import { useMateriels } from "../../hooks/Materiel/useMateriels";
import LoadingSpinner from "../Common/LoadingSpinner";
import { formatDate, formatCurrency, formatDateForInput } from "../../utils/helpers";

const ReparationDetails = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { useGetById, useRemove, useTerminer } = useReparations();
  const { useGetById: useGetMateriel } = useMateriels();
  const { data, isLoading } = useGetById(id);
  const remove = useRemove();
  const terminer = useTerminer();
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [showTerminerForm, setShowTerminerForm] = useState(false);
  const [dateRetour, setDateRetour] = useState(formatDateForInput(new Date()));

  const reparation = data?.data;
  const { data: materielData } = useGetMateriel(reparation?.num_inventaire);
  const materiel = materielData?.data;

  const handleDelete = async () => {
    try {
      await remove.mutateAsync(id);
      navigate("/reparations");
    } catch (error) {
      // toast déjà géré par le hook useRemove
    }
  };

  const handleTerminer = async () => {
    try {
      await terminer.mutateAsync({ id, data: { date_retour: dateRetour } });
      setShowTerminerForm(false);
    } catch (error) {
      // toast déjà géré par le hook useTerminer
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <LoadingSpinner />
      </div>
    );
  }

  if (!reparation) {
    return (
      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        className="text-center py-16"
      >
        <div className="inline-flex items-center justify-center w-20 h-20 rounded-full bg-gray-100 dark:bg-gray-800/50 mb-6">
          <FiInfo className="w-10 h-10 text-gray-400" />
        </div>
        <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-2">
          Réparation non trouvée
        </h3>
        <button
          onClick={() => navigate("/reparations")}
          className="mt-6 inline-flex items-center gap-2 px-6 py-2.5 text-sm font-medium text-white bg-gradient-to-r from-cyan-600 via-blue-600 to-indigo-600 hover:from-cyan-700 hover:via-blue-700 hover:to-indigo-700 rounded-xl transition-all duration-300 shadow-lg"
        >
          <FiArrowLeft className="w-4 h-4" />
          Retour à la liste
        </button>
      </motion.div>
    );
  }

  const isEnCours = !reparation.date_retour;

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      className="space-y-6 max-w-4xl mx-auto px-4"
    >
      <motion.div
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4"
      >
        <div>
          <div className="flex items-center gap-3">
            <span className="p-2.5 rounded-xl bg-gradient-to-br from-orange-500/10 to-amber-500/10">
              <FiTool className="w-6 h-6 text-orange-600 dark:text-orange-400" />
            </span>
            <div>
              <h1 className="text-2xl md:text-3xl font-bold text-gray-900 dark:text-white">
                Réparation N°{reparation.id_reparation}
              </h1>
              <p className="text-gray-500 dark:text-gray-400 mt-1 text-sm">
                {materiel
                  ? `${materiel.marque} ${materiel.modele}`
                  : `Matériel #${reparation.num_inventaire}`}
              </p>
            </div>
          </div>
        </div>
        <div className="flex gap-2">
          <Link
            to={`/reparations/edit/${reparation.id_reparation}`}
            className="inline-flex items-center gap-2 px-5 py-2.5 text-sm font-semibold text-white bg-gradient-to-r from-cyan-600 via-blue-600 to-indigo-600 hover:from-cyan-700 hover:via-blue-700 hover:to-indigo-700 rounded-xl transition-all duration-300 shadow-lg hover:-translate-y-0.5"
          >
            <FiEdit className="w-4 h-4" />
            Modifier
          </Link>
          <button
            onClick={() => setShowDeleteModal(true)}
            className="inline-flex items-center gap-2 px-5 py-2.5 text-sm font-semibold text-white bg-gradient-to-r from-red-600 to-rose-600 hover:from-red-700 hover:to-rose-700 rounded-xl transition-all duration-300 shadow-lg hover:-translate-y-0.5"
          >
            <FiTrash2 className="w-4 h-4" />
            Supprimer
          </button>
        </div>
      </motion.div>

      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className={`rounded-2xl shadow-xl p-6 md:p-8 text-white ${
          isEnCours
            ? "bg-gradient-to-r from-orange-500 to-amber-600"
            : "bg-gradient-to-r from-emerald-500 to-green-600"
        }`}
      >
        <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-6">
          <div className="flex items-center gap-4">
            <div className="p-3 rounded-full bg-white/20">
              {isEnCours ? (
                <FiClock className="w-7 h-7" />
              ) : (
                <FiCheckCircle className="w-7 h-7" />
              )}
            </div>
            <div>
              <p className="text-2xl font-bold">
                {isEnCours ? "En cours" : "Terminée"}
              </p>
              <p className="text-sm text-white/80">
                {isEnCours
                  ? `Constatée le ${formatDate(reparation.date_constat)}`
                  : `Retournée le ${formatDate(reparation.date_retour)}`}
              </p>
            </div>
          </div>
          {isEnCours && (
            <button
              onClick={() => setShowTerminerForm(true)}
              className="inline-flex items-center gap-2 px-5 py-2.5 text-sm font-semibold text-orange-700 bg-white hover:bg-gray-100 rounded-xl transition-all duration-300 shadow-lg"
            >
              <FiCheckCircle className="w-4 h-4" />
              Terminer la réparation
            </button>
          )}
        </div>
      </motion.div>

      {showTerminerForm && (
        <motion.div
          initial={{ opacity: 0, height: 0 }}
          animate={{ opacity: 1, height: "auto" }}
          className="bg-white dark:bg-gray-900 rounded-2xl shadow-xl border border-gray-100/80 dark:border-gray-800/80 p-6"
        >
          <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-3">
            Terminer la réparation
          </h3>
          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">
            Date de retour
          </label>
          <input
            type="date"
            value={dateRetour}
            onChange={(e) => setDateRetour(e.target.value)}
            className="w-full px-4 py-2.5 text-sm border rounded-lg border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
          />
          <div className="flex justify-end gap-3 mt-4">
            <button
              onClick={() => setShowTerminerForm(false)}
              className="px-5 py-2.5 text-sm font-medium text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-xl transition-colors"
            >
              Annuler
            </button>
            <button
              onClick={handleTerminer}
              disabled={terminer.isPending}
              className="px-5 py-2.5 text-sm font-semibold text-white bg-green-600 hover:bg-green-700 rounded-xl transition-colors disabled:opacity-60"
            >
              Confirmer
            </button>
          </div>
        </motion.div>
      )}

      <motion.div className="bg-white dark:bg-gray-900 rounded-2xl shadow-xl border border-gray-100/80 dark:border-gray-800/80 p-6">
        <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-5 flex items-center gap-3">
          <span className="p-2 rounded-xl bg-gradient-to-br from-blue-500/10 to-cyan-500/10 text-blue-600 dark:text-blue-400">
            <FiInfo className="w-5 h-5" />
          </span>
          Détails
        </h3>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 text-sm mb-4">
          <div className="flex items-center gap-2">
            <FiCalendar className="text-gray-400" />
            <span className="text-gray-500 dark:text-gray-400">Date de constat :</span>
            <span className="font-medium text-gray-900 dark:text-white">
              {formatDate(reparation.date_constat)}
            </span>
          </div>
          <div className="flex items-center gap-2">
            <FiUser className="text-gray-400" />
            <span className="text-gray-500 dark:text-gray-400">Prestataire :</span>
            <span className="font-medium text-gray-900 dark:text-white">
              {reparation.prestataire}
            </span>
          </div>
          {reparation.cout && (
            <div className="flex items-center gap-2">
              <FiDollarSign className="text-gray-400" />
              <span className="text-gray-500 dark:text-gray-400">Coût :</span>
              <span className="font-medium text-gray-900 dark:text-white">
                {formatCurrency(reparation.cout)}
              </span>
            </div>
          )}
          {reparation.date_retour && (
            <div className="flex items-center gap-2">
              <FiCalendar className="text-gray-400" />
              <span className="text-gray-500 dark:text-gray-400">Date de retour :</span>
              <span className="font-medium text-gray-900 dark:text-white">
                {formatDate(reparation.date_retour)}
              </span>
            </div>
          )}
        </div>
        <div className="p-4 rounded-xl bg-gray-50 dark:bg-gray-800/30 border border-gray-100 dark:border-gray-800">
          <p className="text-xs font-medium uppercase tracking-wider text-gray-400 dark:text-gray-500 mb-1 flex items-center gap-2">
            <FiFileText className="w-3.5 h-3.5" />
            Description de la panne
          </p>
          <p className="text-gray-700 dark:text-gray-300 whitespace-pre-line">
            {reparation.description_panne}
          </p>
        </div>
      </motion.div>

      {showDeleteModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="bg-white dark:bg-gray-900 rounded-2xl p-6 max-w-md w-full shadow-2xl border border-gray-100 dark:border-gray-800"
          >
            <div className="flex items-center gap-3 text-red-600 dark:text-red-400 mb-4">
              <div className="p-2 rounded-xl bg-red-100 dark:bg-red-900/30">
                <FiAlertCircle className="w-6 h-6" />
              </div>
              <h3 className="text-lg font-bold">Confirmer la suppression</h3>
            </div>
            <p className="text-gray-600 dark:text-gray-400 mb-6 leading-relaxed">
              Êtes-vous sûr de vouloir supprimer cette réparation ?
              <br />
              <span className="text-sm text-red-500 font-medium">
                Cette action est irréversible.
              </span>
            </p>
            <div className="flex justify-end gap-3">
              <button
                onClick={() => setShowDeleteModal(false)}
                className="px-5 py-2.5 text-sm font-medium text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-xl transition-colors"
              >
                Annuler
              </button>
              <button
                onClick={handleDelete}
                className="px-5 py-2.5 text-sm font-semibold text-white bg-gradient-to-r from-red-600 to-rose-600 hover:from-red-700 hover:to-rose-700 rounded-xl transition-all duration-300 shadow-lg"
              >
                <FiTrash2 className="w-4 h-4 inline mr-2" />
                Confirmer la suppression
              </button>
            </div>
          </motion.div>
        </div>
      )}
    </motion.div>
  );
};

export default ReparationDetails;
